import{_ as a,a0 as r,w as l,s as u,ao as x,I as s,x as n,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Linux有問必答：如何顯示Linux網橋的MAC學習表 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何顯示Linux網橋的MAC學習表 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何顯示Linux網橋的MAC學習表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何顯示Linux網橋的MAC學習表 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140825 Linux FAQs with Answers--How to show a MAC learning table of Linux bridge","title":"Linux有問必答：如何顯示Linux網橋的MAC學習表","tag":"201410","desc":""},"relativePath":"201410/20140825 Linux FAQs with Answers--How to show a MAC learning table of Linux bridge.md","filePath":"[post].md"}'),p={name:"201410/20140825 Linux FAQs with Answers--How to show a MAC learning table of Linux bridge.md"};function L(d,t,m,C,A,f){const i=r("Link");return l(),u("div",null,[t[11]||(t[11]=x(`<h1 id="linux有問必答-如何顯示linux網橋的mac學習表" tabindex="-1">Linux有問必答：如何顯示Linux網橋的MAC學習表 <a class="header-anchor" href="#linux有問必答-如何顯示linux網橋的mac學習表" aria-label="Permalink to “Linux有問必答：如何顯示Linux網橋的MAC學習表”">​</a></h1><blockquote><p><strong>問題</strong>：我想要檢查一下我用brctl工具創建的Linux網橋的MAC地址學習狀態。請問，我要怎樣才能查看Linux網橋的MAC學習表（或者轉發表）？</p></blockquote><p>Linux網橋是網橋的軟件實現，這是Linux內核的內核部分。與硬件網橋相類似，Linux網橋維護了一個2層轉發表（也稱為MAC學習表，轉發資料庫，或者僅僅稱為FDB），它跟蹤記錄了MAC地址與端口的對應關係。當一個網橋在端口N收到一個包時（源MAC地址為X），它在FDB中記錄為MAC地址X可以從端口N到達。這樣的話，以後當網橋需要轉發一個包到地址X時，它就可以從FDB查詢知道轉發到哪裏。構建一個FDB常常稱之為“MAC學習”或僅僅稱為“學習”過程。</p><p>你可以使用以下命令來檢查Linux網橋當前轉發表或MAC學習表。</p><pre><code>$ sudo brctl showmacs &lt;bridge-name&gt;
</code></pre><p><img src="https://farm4.staticflickr.com/3856/14963353726_8971873948_z.jpg" alt=""></p><p>該命令將顯示一個學習到的MAC地址與關聯端口的列表。各個條目都有一個相關的附於其上的老化計時器，因此轉發條目可以在一定時間後刷新，以使MAC學習表更新到最新。</p><hr>`,8)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),e(i,{href:"http://ask.xmodulo.com/show-mac-learning-table-linux-bridge.html"},{default:o(()=>[...t[0]||(t[0]=[n("http://ask.xmodulo.com/show-mac-learning-table-linux-bridge.html",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("譯者：",-1)),e(i,{href:"https://github.com/GOLinux"},{default:o(()=>[...t[2]||(t[2]=[n("GOLinux",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[3]||(t[3]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),e(i,{href:"http://linux.cn/"},{default:o(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const T=a(p,[["render",L]]);export{w as __pageData,T as default};
